INSERT INTO public.passages (id, title, content, module, word_count, difficulty, exam_type) VALUES (
INSERT INTO public.questions (id, passage_id, question_text, explanation, difficulty, sort_order, question_type, question_group_label, correct_answer_text, question_data) VALUES
  ('bb000001-e001-4000-8000-000000000001', 'bb000001-0001-0001-0001-000000000001', 'Paragraph B', 'Paragraph B contrasts Cooke and Wheatstone''s five-needle telegraph in England with Morse''s single-wire system in the United States.', 'medium', 1, 'matching_headings', 'Questions 1–5: Matching Headings', 'iii', '{"instruction":"Reading Passage 1 has eight paragraphs, A–H. Choose the correct heading for paragraphs B–F from the list of headings below.","headings":[{"label":"i","text":"A code designed around how often letters are used"},{"label":"ii","text":"Financial losses caused by the new technology"},{"label":"iii","text":"Competing designs in two countries"},{"label":"iv","text":"A publicly funded line proves the idea"},{"label":"v","text":"Linking two continents under the sea"},{"label":"vi","text":"The effect on news, finance and transport"},{"label":"vii","text":"Why operators stopped using paper"},{"label":"viii","text":"The scientific basis of telegraphy"}]}'::jsonb),
  ('bb000001-e002-4000-8000-000000000002', 'bb000001-0001-0001-0001-000000000001', 'Paragraph C', 'Paragraph C explains that the shortest signals were given to the letters used most often in English.', 'medium', 2, 'matching_headings', 'Questions 1–5: Matching Headings', 'i', '{"instruction":"Reading Passage 1 has eight paragraphs, A–H. Choose the correct heading for paragraphs B–F from the list of headings below.","headings":[{"label":"i","text":"A code designed around how often letters are used"},{"label":"ii","text":"Financial losses caused by the new technology"},{"label":"iii","text":"Competing designs in two countries"},{"label":"iv","text":"A publicly funded line proves the idea"},{"label":"v","text":"Linking two continents under the sea"},{"label":"vi","text":"The effect on news, finance and transport"},{"label":"vii","text":"Why operators stopped using paper"},{"label":"viii","text":"The scientific basis of telegraphy"}]}'::jsonb),
  ('bb000001-e003-4000-8000-000000000003', 'bb000001-0001-0001-0001-000000000001', 'Paragraph D', 'The experimental Washington to Baltimore line was paid for by a grant from Congress, and its success led to rapid expansion.', 'medium', 3, 'matching_headings', 'Questions 1–5: Matching Headings', 'iv', '{"instruction":"Reading Passage 1 has eight paragraphs, A–H. Choose the correct heading for paragraphs B–F from the list of headings below.","headings":[{"label":"i","text":"A code designed around how often letters are used"},{"label":"ii","text":"Financial losses caused by the new technology"},{"label":"iii","text":"Competing designs in two countries"},{"label":"iv","text":"A publicly funded line proves the idea"},{"label":"v","text":"Linking two continents under the sea"},{"label":"vi","text":"The effect on news, finance and transport"},{"label":"vii","text":"Why operators stopped using paper"},{"label":"viii","text":"The scientific basis of telegraphy"}]}'::jsonb),
  ('bb000001-e004-4000-8000-000000000004', 'bb000001-0001-0001-0001-000000000001', 'Paragraph E', 'Paragraph E describes the impact on news agencies and newspapers, stock exchanges and railways.', 'medium', 4, 'matching_headings', 'Questions 1–5: Matching Headings', 'vi', '{"instruction":"Reading Passage 1 has eight paragraphs, A–H. Choose the correct heading for paragraphs B–F from the list of headings below.","headings":[{"label":"i","text":"A code designed around how often letters are used"},{"label":"ii","text":"Financial losses caused by the new technology"},{"label":"iii","text":"Competing designs in two countries"},{"label":"iv","text":"A publicly funded line proves the idea"},{"label":"v","text":"Linking two continents under the sea"},{"label":"vi","text":"The effect on news, finance and transport"},{"label":"vii","text":"Why operators stopped using paper"},{"label":"viii","text":"The scientific basis of telegraphy"}]}'::jsonb),
  ('bb000001-e005-4000-8000-000000000005', 'bb000001-0001-0001-0001-000000000001', 'Paragraph F', 'Paragraph F describes the laying of the transatlantic cable between Europe and North America.', 'medium', 5, 'matching_headings', 'Questions 1–5: Matching Headings', 'v', '{"instruction":"Reading Passage 1 has eight paragraphs, A–H. Choose the correct heading for paragraphs B–F from the list of headings below.","headings":[{"label":"i","text":"A code designed around how often letters are used"},{"label":"ii","text":"Financial losses caused by the new technology"},{"label":"iii","text":"Competing designs in two countries"},{"label":"iv","text":"A publicly funded line proves the idea"},{"label":"v","text":"Linking two continents under the sea"},{"label":"vi","text":"The effect on news, finance and transport"},{"label":"vii","text":"Why operators stopped using paper"},{"label":"viii","text":"The scientific basis of telegraphy"}]}'::jsonb),
  ('bb000001-e006-4000-8000-000000000006', 'bb000001-0001-0001-0001-000000000001', 'Volta''s invention produced an electric current that was continuous.', 'Paragraph A: the voltaic pile ''provided the first reliable source of continuous electric current''.', 'medium', 6, 'tfng', 'Questions 6–9: True / False / Not Given', '', '{"instruction":"Do the following statements agree with the information given in Reading Passage 1? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, or NOT GIVEN if there is no information on this."}'::jsonb),
  ('bb000001-e007-4000-8000-000000000007', 'bb000001-0001-0001-0001-000000000001', 'Cooke and Wheatstone''s telegraph was cheaper to install than Morse''s.', 'Paragraph B: the five-needle system needed five wires, ''which made it costly to install'', while Morse''s was ''more economical''.', 'medium', 7, 'tfng', 'Questions 6–9: True / False / Not Given', '', '{"instruction":"Do the following statements agree with the information given in Reading Passage 1? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, or NOT GIVEN if there is no information on this."}'::jsonb),
  ('bb000001-e008-4000-8000-000000000008', 'bb000001-0001-0001-0001-000000000001', 'Alfred Vail had worked in the printing industry before he met Morse.', 'Paragraph C says Vail counted type in a printing office, but nothing is said about where he had worked.', 'medium', 8, 'tfng', 'Questions 6–9: True / False / Not Given', '', '{"instruction":"Do the following statements agree with the information given in Reading Passage 1? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, or NOT GIVEN if there is no information on this."}'::jsonb),
  ('bb000001-e009-4000-8000-000000000009', 'bb000001-0001-0001-0001-000000000001', 'The transatlantic cable of 1858 remained in service for several years.', 'Paragraph F: the 1858 cable ''worked for only three weeks''.', 'medium', 9, 'tfng', 'Questions 6–9: True / False / Not Given', '', '{"instruction":"Do the following statements agree with the information given in Reading Passage 1? Choose TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, or NOT GIVEN if there is no information on this."}'::jsonb),
  ('bb000001-e010-4000-8000-000000000010', 'bb000001-0001-0001-0001-000000000001', 'Spring-loaded lever pressed by the operator', 'Paragraph G: ''the operator pressed down a spring-loaded lever known as the key''.', 'medium', 10, 'diagram_label', 'Questions 10–13: Diagram Label Completion', 'key', '{"instruction":"Label the diagram below. Choose NO MORE THAN TWO WORDS from the passage for each answer.","diagram":"morse-telegraph","diagram_title":"A Morse telegraph line","max_words":2}'::jsonb),
  ('bb000001-e011-4000-8000-000000000011', 'bb000001-0001-0001-0001-000000000001', 'Its coils carry the current at the receiving station', 'Paragraph G: ''the current passed through the coils of an electromagnet''.', 'medium', 11, 'diagram_label', 'Questions 10–13: Diagram Label Completion', 'electromagnet', '{"instruction":"Label the diagram below. Choose NO MORE THAN TWO WORDS from the passage for each answer.","diagram":"morse-telegraph","diagram_title":"A Morse telegraph line","max_words":2}'::jsonb),
  ('bb000001-e012-4000-8000-000000000012', 'bb000001-0001-0001-0001-000000000001', 'Pivoted iron bar pulled down at one end', 'Paragraph G: ''a pivoted iron bar called the armature''.', 'medium', 12, 'diagram_label', 'Questions 10–13: Diagram Label Completion', 'armature', '{"instruction":"Label the diagram below. Choose NO MORE THAN TWO WORDS from the passage for each answer.","diagram":"morse-telegraph","diagram_title":"A Morse telegraph line","max_words":2}'::jsonb),
  ('bb000001-e013-4000-8000-000000000013', 'bb000001-0001-0001-0001-000000000001', 'Strip on which dots and dashes are embossed', 'Paragraph G: the stylus was pushed up against ''a strip of paper tape''.', 'medium', 13, 'diagram_label', 'Questions 10–13: Diagram Label Completion', 'paper tape|tape', '{"instruction":"Label the diagram below. Choose NO MORE THAN TWO WORDS from the passage for each answer.","diagram":"morse-telegraph","diagram_title":"A Morse telegraph line","max_words":2}'::jsonb);
