INSERT INTO public.questions (id, passage_id, question_text, explanation, difficulty, sort_order, question_type, question_group_label, correct_answer_text, question_data) VALUES
  ('bb000002-e014-4000-8000-000000000014', 'bb000002-0002-0002-0002-000000000002', 'What does the writer say about bioluminescence in paragraph A?', 'Paragraph A: ''an estimated 76 percent of all ocean creatures'' below 200 metres can produce light.', 'medium', 14, 'multiple_choice', 'Questions 14–17: Multiple Choice', '', '{"instruction":"Choose the correct letter, A, B, C or D."}'::jsonb),
  ('bb000002-e015-4000-8000-000000000015', 'bb000002-0002-0002-0002-000000000002', 'Bioluminescence is described as ''cold light'' because', 'Paragraph B: the reaction releases light ''with remarkably little heat'' and converts nearly all its energy into light.', 'medium', 15, 'multiple_choice', 'Questions 14–17: Multiple Choice', '', '{"instruction":"Choose the correct letter, A, B, C or D."}'::jsonb),
  ('bb000002-e016-4000-8000-000000000016', 'bb000002-0002-0002-0002-000000000002', 'Why do most deep-sea animals produce blue or green light?', 'Paragraph C: ''these wavelengths travel furthest through seawater''.', 'medium', 16, 'multiple_choice', 'Questions 14–17: Multiple Choice', '', '{"instruction":"Choose the correct letter, A, B, C or D."}'::jsonb),
  ('bb000002-e017-4000-8000-000000000017', 'bb000002-0002-0002-0002-000000000002', 'What is said about green fluorescent protein?', 'Paragraph H: researchers can ''watch biological processes in living organisms in real time''.', 'medium', 17, 'multiple_choice', 'Questions 14–17: Multiple Choice', '', '{"instruction":"Choose the correct letter, A, B, C or D."}'::jsonb),
  ('bb000002-e018-4000-8000-000000000018', 'bb000002-0002-0002-0002-000000000002', 'It depends on another organism to produce its light.', 'Paragraph E: the anglerfish''s light is produced ''by bacteria living in the lure''.', 'medium', 18, 'matching_features', 'Questions 18–22: Matching Features', 'C', '{"instruction":"Look at the following statements and the list of animals below. Match each statement with the correct animal, A–F.","list_title":"List of Animals","features":[{"label":"A","text":"hatchetfish"},{"label":"B","text":"deep-sea shrimp"},{"label":"C","text":"anglerfish"},{"label":"D","text":"dragonfish"},{"label":"E","text":"firefly squid"},{"label":"F","text":"jellyfish"}]}'::jsonb),
  ('bb000002-e019-4000-8000-000000000019', 'bb000002-0002-0002-0002-000000000002', 'It gives out light of a colour that its prey is unable to see.', 'Paragraph E: the dragonfish produces red light, which most deep-sea creatures cannot see.', 'medium', 19, 'matching_features', 'Questions 18–22: Matching Features', 'D', '{"instruction":"Look at the following statements and the list of animals below. Match each statement with the correct animal, A–F.","list_title":"List of Animals","features":[{"label":"A","text":"hatchetfish"},{"label":"B","text":"deep-sea shrimp"},{"label":"C","text":"anglerfish"},{"label":"D","text":"dragonfish"},{"label":"E","text":"firefly squid"},{"label":"F","text":"jellyfish"}]}'::jsonb),
  ('bb000002-e020-4000-8000-000000000020', 'bb000002-0002-0002-0002-000000000002', 'It alters the strength of its light to match its surroundings.', 'Paragraph D: the hatchetfish ''can even adjust their brightness as the light from above changes''.', 'medium', 20, 'matching_features', 'Questions 18–22: Matching Features', 'A', '{"instruction":"Look at the following statements and the list of animals below. Match each statement with the correct animal, A–F.","list_title":"List of Animals","features":[{"label":"A","text":"hatchetfish"},{"label":"B","text":"deep-sea shrimp"},{"label":"C","text":"anglerfish"},{"label":"D","text":"dragonfish"},{"label":"E","text":"firefly squid"},{"label":"F","text":"jellyfish"}]}'::jsonb),
  ('bb000002-e021-4000-8000-000000000021', 'bb000002-0002-0002-0002-000000000002', 'It gathers in very large numbers to produce light displays.', 'Paragraph F: ''millions of individuals gather near the shore and create a dazzling light show''.', 'medium', 21, 'matching_features', 'Questions 18–22: Matching Features', 'E', '{"instruction":"Look at the following statements and the list of animals below. Match each statement with the correct animal, A–F.","list_title":"List of Animals","features":[{"label":"A","text":"hatchetfish"},{"label":"B","text":"deep-sea shrimp"},{"label":"C","text":"anglerfish"},{"label":"D","text":"dragonfish"},{"label":"E","text":"firefly squid"},{"label":"F","text":"jellyfish"}]}'::jsonb),
  ('bb000002-e022-4000-8000-000000000022', 'bb000002-0002-0002-0002-000000000002', 'Its light may cause its attacker to be attacked.', 'Paragraph F: jellyfish attract ''even larger predators, which may in turn attack the original attacker''.', 'medium', 22, 'matching_features', 'Questions 18–22: Matching Features', 'F', '{"instruction":"Look at the following statements and the list of animals below. Match each statement with the correct animal, A–F.","list_title":"List of Animals","features":[{"label":"A","text":"hatchetfish"},{"label":"B","text":"deep-sea shrimp"},{"label":"C","text":"anglerfish"},{"label":"D","text":"dragonfish"},{"label":"E","text":"firefly squid"},{"label":"F","text":"jellyfish"}]}'::jsonb),
  ('bb000002-e023-4000-8000-000000000023', 'bb000002-0002-0002-0002-000000000002', '', 'Paragraph D: ''rows of light organs called photophores along its belly''.', 'medium', 23, 'table_completion', 'Questions 23–26: Table Completion', 'belly|underside|undersides', '{"instruction":"Complete the table below. Choose ONE WORD ONLY from the passage for each answer.","table_title":"Uses of bioluminescence","max_words":1,"columns":["Purpose","How the light is used","Example"],"rows":[["Defence","light organs along the __BLANK__ hide the animal''s outline from below","hatchetfish"],["Defence","a __BLANK__ of glowing fluid confuses the attacker","deep-sea shrimp"],["Hunting","a luminous lure on a modified __BLANK__ attracts prey","anglerfish"],["Communication","light displays take place during the __BLANK__ season","firefly squid"]]}'::jsonb),
  ('bb000002-e024-4000-8000-000000000024', 'bb000002-0002-0002-0002-000000000002', '', 'Paragraph D: shrimp ''spit out a cloud of glowing fluid''.', 'medium', 24, 'table_completion', 'Questions 23–26: Table Completion', 'cloud', '{"instruction":"Complete the table below. Choose ONE WORD ONLY from the passage for each answer.","table_title":"Uses of bioluminescence","max_words":1,"columns":["Purpose","How the light is used","Example"],"rows":[["Defence","light organs along the __BLANK__ hide the animal''s outline from below","hatchetfish"],["Defence","a __BLANK__ of glowing fluid confuses the attacker","deep-sea shrimp"],["Hunting","a luminous lure on a modified __BLANK__ attracts prey","anglerfish"],["Communication","light displays take place during the __BLANK__ season","firefly squid"]]}'::jsonb),
  ('bb000002-e025-4000-8000-000000000025', 'bb000002-0002-0002-0002-000000000002', '', 'Paragraph E: ''a modified dorsal spine tipped with a luminous lure''.', 'medium', 25, 'table_completion', 'Questions 23–26: Table Completion', 'spine', '{"instruction":"Complete the table below. Choose ONE WORD ONLY from the passage for each answer.","table_title":"Uses of bioluminescence","max_words":1,"columns":["Purpose","How the light is used","Example"],"rows":[["Defence","light organs along the __BLANK__ hide the animal''s outline from below","hatchetfish"],["Defence","a __BLANK__ of glowing fluid confuses the attacker","deep-sea shrimp"],["Hunting","a luminous lure on a modified __BLANK__ attracts prey","anglerfish"],["Communication","light displays take place during the __BLANK__ season","firefly squid"]]}'::jsonb),
  ('bb000002-e026-4000-8000-000000000026', 'bb000002-0002-0002-0002-000000000002', '', 'Paragraph F: ''spectacular displays during the mating season''.', 'medium', 26, 'table_completion', 'Questions 23–26: Table Completion', 'mating', '{"instruction":"Complete the table below. Choose ONE WORD ONLY from the passage for each answer.","table_title":"Uses of bioluminescence","max_words":1,"columns":["Purpose","How the light is used","Example"],"rows":[["Defence","light organs along the __BLANK__ hide the animal''s outline from below","hatchetfish"],["Defence","a __BLANK__ of glowing fluid confuses the attacker","deep-sea shrimp"],["Hunting","a luminous lure on a modified __BLANK__ attracts prey","anglerfish"],["Communication","light displays take place during the __BLANK__ season","firefly squid"]]}'::jsonb);
INSERT INTO public.options (question_id, option_label, option_text, is_correct, sort_order) VALUES
  ('bb000002-e014-4000-8000-000000000014', 'A', 'It is rarer in the deep sea than near the surface.', false, 1),
  ('bb000002-e014-4000-8000-000000000014', 'B', 'It was studied in detail long before the twentieth century.', false, 2),
  ('bb000002-e014-4000-8000-000000000014', 'C', 'It is found in the majority of animals living below 200 metres.', true, 3),
  ('bb000002-e014-4000-8000-000000000014', 'D', 'It is a curiosity with little biological function.', false, 4),
  ('bb000002-e015-4000-8000-000000000015', 'A', 'it occurs only in very cold water.', false, 1),
  ('bb000002-e015-4000-8000-000000000015', 'B', 'the reaction wastes very little energy as heat.', true, 2),
  ('bb000002-e015-4000-8000-000000000015', 'C', 'the light it produces is blue.', false, 3),
  ('bb000002-e015-4000-8000-000000000015', 'D', 'it takes place without oxygen.', false, 4),
  ('bb000002-e016-4000-8000-000000000016', 'A', 'These colours are the easiest to produce chemically.', false, 1),
  ('bb000002-e016-4000-8000-000000000016', 'B', 'These colours cannot be seen by predators.', false, 2),
  ('bb000002-e016-4000-8000-000000000016', 'C', 'These colours are transmitted furthest through seawater.', true, 3),
  ('bb000002-e016-4000-8000-000000000016', 'D', 'Their food contains blue and green luciferin.', false, 4),
  ('bb000002-e017-4000-8000-000000000017', 'A', 'It was first obtained from a species of squid.', false, 1),
  ('bb000002-e017-4000-8000-000000000017', 'B', 'It allows scientists to observe processes inside living things.', true, 2),
  ('bb000002-e017-4000-8000-000000000017', 'C', 'It is already used to light streets and buildings.', false, 3),
  ('bb000002-e017-4000-8000-000000000017', 'D', 'Its discoverers were awarded a Nobel Prize in the 1960s.', false, 4);
INSERT INTO public.passages (id, title, content, module, word_count, difficulty, exam_type) VALUES (
INSERT INTO public.questions (id, passage_id, question_text, explanation, difficulty, sort_order, question_type, question_group_label, correct_answer_text, question_data) VALUES
  ('bb000003-e027-4000-8000-000000000027', 'bb000003-0003-0003-0003-000000000003', 'The drainage of Indus Valley cities was superior to anything in Europe for a very long time.', 'Paragraph A: their drainage systems ''would not be equalled in Europe for thousands of years''.', 'hard', 27, 'yng', 'Questions 27–31: Yes / No / Not Given', '', '{"instruction":"Do the following statements agree with the views of the writer in Reading Passage 3? Choose YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, or NOT GIVEN if it is impossible to say what the writer thinks about this."}'::jsonb),
  ('bb000003-e028-4000-8000-000000000028', 'bb000003-0003-0003-0003-000000000003', 'Medieval towns deserve the admiration they receive today.', 'Paragraph B: the writer says this view ''could only be held by people who never had to live in them''.', 'hard', 28, 'yng', 'Questions 27–31: Yes / No / Not Given', '', '{"instruction":"Do the following statements agree with the views of the writer in Reading Passage 3? Choose YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, or NOT GIVEN if it is impossible to say what the writer thinks about this."}'::jsonb),
  ('bb000003-e029-4000-8000-000000000029', 'bb000003-0003-0003-0003-000000000003', 'The Garden City movement should be regarded as a failure.', 'Paragraph E: critics have called it a failure, but the writer says ''This is unfair''.', 'hard', 29, 'yng', 'Questions 27–31: Yes / No / Not Given', '', '{"instruction":"Do the following statements agree with the views of the writer in Reading Passage 3? Choose YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, or NOT GIVEN if it is impossible to say what the writer thinks about this."}'::jsonb),
  ('bb000003-e030-4000-8000-000000000030', 'bb000003-0003-0003-0003-000000000003', 'Le Corbusier''s ideas were adopted more widely in Europe than in America.', 'Paragraph F says the principles were adopted with enthusiasm after 1945, but does not compare regions.', 'hard', 30, 'yng', 'Questions 27–31: Yes / No / Not Given', '', '{"instruction":"Do the following statements agree with the views of the writer in Reading Passage 3? Choose YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, or NOT GIVEN if it is impossible to say what the writer thinks about this."}'::jsonb),
  ('bb000003-e031-4000-8000-000000000031', 'bb000003-0003-0003-0003-000000000003', 'Jane Jacobs understood cities better than the planners who criticised her.', 'Paragraph G: ''time has shown that her observations were sounder than their theories''.', 'hard', 31, 'yng', 'Questions 27–31: Yes / No / Not Given', '', '{"instruction":"Do the following statements agree with the views of the writer in Reading Passage 3? Choose YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, or NOT GIVEN if it is impossible to say what the writer thinks about this."}'::jsonb),
  ('bb000003-e032-4000-8000-000000000032', 'bb000003-0003-0003-0003-000000000003', '', 'Paragraph F: ''high-rise towers set in open parkland''.', 'hard', 32, 'summary_completion', 'Questions 32–35: Summary Completion', 'parkland', '{"instruction":"Complete the summary using the list of words below. Choose ONE WORD ONLY from the list for each answer.","summary_title":"Modernist planning","has_word_list":true,"word_list":["greenbelts","sanitation","legislation","parkland","communities","pollution","zoning","markets"],"summary_text":"Le Corbusier proposed a city of tall towers standing in __BLANK__ and linked by motorways. Each district was to have a single function, a system known as __BLANK__. The new housing gave many families better __BLANK__ than the slums they had left, but the schemes broke up existing __BLANK__ and made residents rely on cars."}'::jsonb),
  ('bb000003-e033-4000-8000-000000000033', 'bb000003-0003-0003-0003-000000000003', '', 'Paragraph F: ''strict zoning to separate the places where people lived, worked and shopped''.', 'hard', 33, 'summary_completion', 'Questions 32–35: Summary Completion', 'zoning', '{"instruction":"Complete the summary using the list of words below. Choose ONE WORD ONLY from the list for each answer.","summary_title":"Modernist planning","has_word_list":true,"word_list":["greenbelts","sanitation","legislation","parkland","communities","pollution","zoning","markets"],"summary_text":"Le Corbusier proposed a city of tall towers standing in __BLANK__ and linked by motorways. Each district was to have a single function, a system known as __BLANK__. The new housing gave many families better __BLANK__ than the slums they had left, but the schemes broke up existing __BLANK__ and made residents rely on cars."}'::jsonb),
  ('bb000003-e034-4000-8000-000000000034', 'bb000003-0003-0003-0003-000000000003', '', 'Paragraph F: the towers ''offered light, space and sanitation''.', 'hard', 34, 'summary_completion', 'Questions 32–35: Summary Completion', 'sanitation', '{"instruction":"Complete the summary using the list of words below. Choose ONE WORD ONLY from the list for each answer.","summary_title":"Modernist planning","has_word_list":true,"word_list":["greenbelts","sanitation","legislation","parkland","communities","pollution","zoning","markets"],"summary_text":"Le Corbusier proposed a city of tall towers standing in __BLANK__ and linked by motorways. Each district was to have a single function, a system known as __BLANK__. The new housing gave many families better __BLANK__ than the slums they had left, but the schemes broke up existing __BLANK__ and made residents rely on cars."}'::jsonb),
  ('bb000003-e035-4000-8000-000000000035', 'bb000003-0003-0003-0003-000000000003', '', 'Paragraph F: ''communities were scattered''.', 'hard', 35, 'summary_completion', 'Questions 32–35: Summary Completion', 'communities', '{"instruction":"Complete the summary using the list of words below. Choose ONE WORD ONLY from the list for each answer.","summary_title":"Modernist planning","has_word_list":true,"word_list":["greenbelts","sanitation","legislation","parkland","communities","pollution","zoning","markets"],"summary_text":"Le Corbusier proposed a city of tall towers standing in __BLANK__ and linked by motorways. Each district was to have a single function, a system known as __BLANK__. The new housing gave many families better __BLANK__ than the slums they had left, but the schemes broke up existing __BLANK__ and made residents rely on cars."}'::jsonb),
  ('bb000003-e036-4000-8000-000000000036', 'bb000003-0003-0003-0003-000000000003', '', 'Paragraph A: ''covered drainage systems''.', 'hard', 36, 'flowchart_completion', 'Questions 36–40: Flow-chart Completion', 'drainage', '{"instruction":"Complete the flow chart below. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the passage for each answer.","flowchart_title":"The development of urban planning","max_words":3,"nodes":[{"text":"Indus Valley cities are built with grid streets and covered __BLANK__ systems"},{"text":"Greeks develop the grid plan; Romans place a __BLANK__ at the centre of each new town"},{"text":"Medieval towns grow without a plan inside their walls"},{"text":"Overcrowding in industrial towns leads to the __BLANK__ of 1848"},{"text":"1898: Howard proposes communities surrounded by __BLANK__"},{"text":"After 1945: modernist towers and motorways"},{"text":"Today: the 15-minute city; __BLANK__ percent of people expected to live in cities by 2050"}]}'::jsonb),
  ('bb000003-e037-4000-8000-000000000037', 'bb000003-0003-0003-0003-000000000003', '', 'Paragraph A: ''placing a forum at the heart of each new town''.', 'hard', 37, 'flowchart_completion', 'Questions 36–40: Flow-chart Completion', 'forum', '{"instruction":"Complete the flow chart below. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the passage for each answer.","flowchart_title":"The development of urban planning","max_words":3,"nodes":[{"text":"Indus Valley cities are built with grid streets and covered __BLANK__ systems"},{"text":"Greeks develop the grid plan; Romans place a __BLANK__ at the centre of each new town"},{"text":"Medieval towns grow without a plan inside their walls"},{"text":"Overcrowding in industrial towns leads to the __BLANK__ of 1848"},{"text":"1898: Howard proposes communities surrounded by __BLANK__"},{"text":"After 1945: modernist towers and motorways"},{"text":"Today: the 15-minute city; __BLANK__ percent of people expected to live in cities by 2050"}]}'::jsonb),
  ('bb000003-e038-4000-8000-000000000038', 'bb000003-0003-0003-0003-000000000003', '', 'Paragraph C: ''The Public Health Act of 1848''.', 'hard', 38, 'flowchart_completion', 'Questions 36–40: Flow-chart Completion', 'Public Health Act', '{"instruction":"Complete the flow chart below. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the passage for each answer.","flowchart_title":"The development of urban planning","max_words":3,"nodes":[{"text":"Indus Valley cities are built with grid streets and covered __BLANK__ systems"},{"text":"Greeks develop the grid plan; Romans place a __BLANK__ at the centre of each new town"},{"text":"Medieval towns grow without a plan inside their walls"},{"text":"Overcrowding in industrial towns leads to the __BLANK__ of 1848"},{"text":"1898: Howard proposes communities surrounded by __BLANK__"},{"text":"After 1945: modernist towers and motorways"},{"text":"Today: the 15-minute city; __BLANK__ percent of people expected to live in cities by 2050"}]}'::jsonb),
  ('bb000003-e039-4000-8000-000000000039', 'bb000003-0003-0003-0003-000000000003', '', 'Paragraph E: ''self-contained communities surrounded by greenbelts''.', 'hard', 39, 'flowchart_completion', 'Questions 36–40: Flow-chart Completion', 'greenbelts|green belts', '{"instruction":"Complete the flow chart below. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the passage for each answer.","flowchart_title":"The development of urban planning","max_words":3,"nodes":[{"text":"Indus Valley cities are built with grid streets and covered __BLANK__ systems"},{"text":"Greeks develop the grid plan; Romans place a __BLANK__ at the centre of each new town"},{"text":"Medieval towns grow without a plan inside their walls"},{"text":"Overcrowding in industrial towns leads to the __BLANK__ of 1848"},{"text":"1898: Howard proposes communities surrounded by __BLANK__"},{"text":"After 1945: modernist towers and motorways"},{"text":"Today: the 15-minute city; __BLANK__ percent of people expected to live in cities by 2050"}]}'::jsonb),
  ('bb000003-e040-4000-8000-000000000040', 'bb000003-0003-0003-0003-000000000003', '', 'Paragraph H: ''68 percent of the world''s population projected to live in urban areas by 2050''.', 'hard', 40, 'flowchart_completion', 'Questions 36–40: Flow-chart Completion', '68', '{"instruction":"Complete the flow chart below. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the passage for each answer.","flowchart_title":"The development of urban planning","max_words":3,"nodes":[{"text":"Indus Valley cities are built with grid streets and covered __BLANK__ systems"},{"text":"Greeks develop the grid plan; Romans place a __BLANK__ at the centre of each new town"},{"text":"Medieval towns grow without a plan inside their walls"},{"text":"Overcrowding in industrial towns leads to the __BLANK__ of 1848"},{"text":"1898: Howard proposes communities surrounded by __BLANK__"},{"text":"After 1945: modernist towers and motorways"},{"text":"Today: the 15-minute city; __BLANK__ percent of people expected to live in cities by 2050"}]}'::jsonb);
