INSERT INTO public.questions (id, passage_id, question_text, explanation, difficulty, sort_order, question_type, question_group_label, correct_answer_text, question_data) VALUES
  ('cc020001-e001-4000-8000-000000000001', 'cc020001-0001-0001-0001-000000000001', 'de__', 'The complete word is "deep".', 'medium', 1, 'complete_words', 'Questions 1–10: Complete the Words', 'ep', '{"instruction":"Fill in the missing letters in the paragraph.","template":"Scientists have long suspected that sleep does more than rest the body. During {{1}} sleep, {{2}} brain {{3}} the {{4}} of {{5}} day {{6}} moves {{7}} information {{8}} permanent {{9}}. Students {{10}} sleep after studying usually remember more than those who stay awake. Even a short nap can improve the recall of new facts. For this reason, researchers advise against studying all night before an examination. A regular sleep schedule may therefore be as valuable as extra hours of revision.","prefix":"de","missing":2}'::jsonb),
