  ('cc020003-e021-4000-8000-000000000021', 'cc020003-0003-0003-0003-000000000003', 'What is the main purpose of the notice?', 'The notice gives the library''s reduced summer opening hours.', 'easy', 21, 'multiple_choice', 'Questions 21–22: Read in Daily Life', '', '{"task":"daily_life","hide_instruction":true}'::jsonb),
