INSERT INTO public.questions (id, passage_id, question_text, explanation, difficulty, sort_order, question_type, question_group_label, correct_answer_text, question_data) VALUES
  ('cc020004-e023-4000-8000-000000000023', 'cc020004-0004-0004-0004-000000000004', 'Why has the lab session been moved?', 'The heating system in Room 114 ''is being repaired this week''.', 'medium', 23, 'multiple_choice', 'Questions 23–25: Read in Daily Life', '', '{"task":"daily_life","hide_instruction":true}'::jsonb),
  ('cc020004-e024-4000-8000-000000000024', 'cc020004-0004-0004-0004-000000000004', 'What are students told to bring?', 'Students must bring their own lab coat and goggles because the Annex has no spare equipment.', 'medium', 24, 'multiple_choice', 'Questions 23–25: Read in Daily Life', '', '{"task":"daily_life","hide_instruction":true}'::jsonb),
  ('cc020004-e025-4000-8000-000000000025', 'cc020004-0004-0004-0004-000000000004', 'What can be inferred about students who cannot attend on Thursday?', 'Dr. Marsh offers to ''arrange a place for you in Friday''s group''.', 'medium', 25, 'multiple_choice', 'Questions 23–25: Read in Daily Life', '', '{"task":"daily_life","hide_instruction":true}'::jsonb);
