  ('cc020004-e023-4000-8000-000000000023', 'C', 'The Annex has better equipment.', false, 3),
  ('cc020004-e023-4000-8000-000000000023', 'D', 'Friday''s group is already full.', false, 4),
  ('cc020004-e024-4000-8000-000000000024', 'A', 'Their own safety equipment', true, 1),
