INSERT INTO public.passages (id, title, content, module, word_count, difficulty, exam_type) VALUES (
INSERT INTO public.questions (id, passage_id, question_text, explanation, difficulty, sort_order, question_type, question_group_label, correct_answer_text, question_data) VALUES
  ('cc020005-e026-4000-8000-000000000026', 'cc020005-0005-0005-0005-000000000005', 'What is the passage mainly about?', 'The passage explains the waggle dance, which ''tells other workers where the food is''.', 'medium', 26, 'multiple_choice', 'Questions 26–30: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb),
  ('cc020005-e027-4000-8000-000000000027', 'cc020005-0005-0005-0005-000000000005', 'According to paragraph 1, what does the length of the straight run indicate?', '''The duration of the run conveys distance: the longer the waggle, the farther the flowers.''', 'medium', 27, 'multiple_choice', 'Questions 26–30: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb),
  ('cc020005-e028-4000-8000-000000000028', 'cc020005-0005-0005-0005-000000000005', 'The word "scepticism" in the passage is closest in meaning to', 'Scepticism means doubt: many researchers did not at first accept von Frisch''s conclusions.', 'medium', 28, 'multiple_choice', 'Questions 26–30: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb),
  ('cc020005-e029-4000-8000-000000000029', 'cc020005-0005-0005-0005-000000000005', 'Why does the author mention robotic bees?', 'Robotic bees carried no odour, yet recruits still found the food, so the dance must carry the information.', 'medium', 29, 'multiple_choice', 'Questions 26–30: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb),
  ('cc020005-e030-4000-8000-000000000030', 'cc020005-0005-0005-0005-000000000005', 'What can be inferred about scent from the passage?', 'Scent helps bees ''pinpoint the flowers once they have arrived in the right area''.', 'medium', 30, 'multiple_choice', 'Questions 26–30: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb);
