INSERT INTO public.questions (id, passage_id, question_text, explanation, difficulty, sort_order, question_type, question_group_label, correct_answer_text, question_data) VALUES
  ('cc020009-e046-4000-8000-000000000046', 'cc020009-0009-0009-0009-000000000009', 'According to paragraph 1, which of the following was an effect of the Little Ice Age?', '''Shorter growing seasons led to repeated crop failures.''', 'hard', 46, 'multiple_choice', 'Questions 46–50: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb),
  ('cc020009-e047-4000-8000-000000000047', 'cc020009-0009-0009-0009-000000000009', 'The word "modest" in the passage is closest in meaning to', 'The cooling was only about one degree Celsius, so ''modest'' means small.', 'hard', 47, 'multiple_choice', 'Questions 46–50: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb),
  ('cc020009-e048-4000-8000-000000000048', 'cc020009-0009-0009-0009-000000000009', 'What do most researchers now believe caused the cooling?', '''Neither factor alone seems sufficient, and most researchers now believe that the two acted together.''', 'hard', 48, 'multiple_choice', 'Questions 46–50: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb),
  ('cc020009-e049-4000-8000-000000000049', 'cc020009-0009-0009-0009-000000000009', 'Why does the author mention sunspots?', 'The scarcity of sunspots is given as the sign that the sun ''appears to have been less active''.', 'hard', 49, 'multiple_choice', 'Questions 46–50: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb),
  ('cc020009-e050-4000-8000-000000000050', 'cc020009-0009-0009-0009-000000000009', 'What is the main point of paragraph 3?', 'The period shows ''both the vulnerability of human communities to climate and their capacity to adapt''.', 'hard', 50, 'multiple_choice', 'Questions 46–50: Read an Academic Passage', '', '{"task":"academic","hide_instruction":true}'::jsonb);
